INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-01','AM Modulation Index','Easy','ECE','arena','calculate','Communication Systems','multiple_choice','An AM signal has carrier amplitude A_c = 10 V and message amplitude A_m = 4 V. What is the modulation index?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-02','FM Deviation and Bandwidth (Carson''s Rule)','Easy','ECE','arena','calculate','Communication Systems','multiple_choice','An FM transmitter has maximum frequency deviation Δf = 75 kHz and message frequency f_m = 15 kHz. Using Carson''s rule, what is the approximate bandwidth?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-03','Nyquist Sampling Rate','Easy','ECE','arena','calculate','Communication Systems','multiple_choice','A signal has a maximum frequency of 4 kHz. What is the minimum sampling rate required to avoid aliasing?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-04','PCM Bit Rate Calculation','Easy','ECE','arena','calculate','Communication Systems','multiple_choice','A PCM system samples a voice signal at 8 kHz with 8-bit quantisation. What is the bit rate?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-05','AM Sidebands','Easy','ECE','arena','predict','Communication Systems','multiple_choice','An AM carrier at 1000 kHz is modulated by a 5 kHz audio tone. What frequencies appear in the output spectrum?','{"choices": ["1000 kHz only", "995 kHz, 1000 kHz, and 1005 kHz", "995 kHz and 1005 kHz only", "1000 kHz and 1005 kHz"], "correct": 1}'::jsonb,'AM produces: carrier (f_c) + upper sideband (f_c + f_m) + lower sideband (f_c − f_m) = 995, 1000, 1005 kHz. The sidebands carry the actual information; the carrier carries no information.','{multiple_choice}'::text[],0.84) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-06','Signal-to-Noise Ratio Calculation','Easy','ECE','arena','calculate','Communication Systems','multiple_choice','A communication system measures signal power = 100 mW and noise power = 0.1 mW. What is the SNR in dB?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-07','Frequency Division Multiplexing','Easy','ECE','arena','select','Communication Systems','multiple_choice','FDM (Frequency Division Multiplexing) combines multiple signals by:','{"choices": ["Allocating different time slots to each signal", "Converting all signals to digital and interleaving bits", "Translating each signal to a different carrier frequency and transmitting simultaneously", "Spreading each signal over the full bandwidth using different codes"], "correct": 2}'::jsonb,'FDM assigns each channel a unique carrier frequency (sub-band). All channels are transmitted simultaneously over different frequency bands — like radio stations on different frequencies. Used in cable TV, telephone networks.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-08','QPSK Bits per Symbol','Easy','ECE','arena','calculate','Communication Systems','multiple_choice','QPSK (Quadrature Phase Shift Keying) uses 4 different phase states. How many bits does each symbol carry?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-09','Bandwidth Efficiency','Medium','ECE','arena','calculate','Communication Systems','multiple_choice','A 16-QAM system operates with symbol rate 10 Msymbols/s. What is the bit rate?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-10','Shannon Channel Capacity','Medium','ECE','arena','calculate','Communication Systems','multiple_choice','A channel has bandwidth B = 200 kHz and SNR = 31 (linear). What is the Shannon channel capacity?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-11','Free Space Path Loss','Medium','ECE','arena','calculate','Communication Systems','multiple_choice','A 2.4 GHz WiFi signal travels 100 m in free space. What is the approximate path loss?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-12','CDMA Spreading Gain','Medium','ECE','arena','interpret','Communication Systems','multiple_choice','In CDMA, a voice channel at 9.6 kbps is spread over a 1.2288 MHz bandwidth. What is the processing gain?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-13','AM Power Distribution','Medium','ECE','arena','calculate','Communication Systems','multiple_choice','An AM transmitter has carrier power P_c = 10 kW and modulation index m = 0.8. What is the total transmitted power?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-14','OFDM Subcarrier Orthogonality','Medium','ECE','arena','interpret','Communication Systems','multiple_choice','OFDM (Orthogonal Frequency Division Multiplexing) achieves spectral efficiency through:','{"choices": ["Using very narrow guard bands between carriers", "Subcarrier spacing = 1/T where T is symbol duration — subcarriers are mathematically orthogonal, allowing spectral overlap without interference", "Only using QPSK modulation on each subcarrier", "High-power amplifiers"], "correct": 1}'::jsonb,'OFDM subcarriers are spaced by exactly 1/T (inverse of symbol duration). At the peak of each subcarrier, all other subcarriers are at zero — orthogonality allows overlapping without ICI. Used in LTE, 5G, WiFi, DVB.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-15','Friis Transmission Equation','Medium','ECE','arena','calculate','Communication Systems','multiple_choice','A transmitter outputs 10 W with antenna gain G_T = 10 dBi. Receiver antenna gain G_R = 5 dBi, distance = 1 km, frequency = 1 GHz. What is the received power (use Friis equation)?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-16','Error Detection: CRC','Medium','ECE','arena','select','Communication Systems','multiple_choice','CRC (Cyclic Redundancy Check) is primarily used in digital communications for:','{"choices": ["Encryption of data", "Compression of data", "Error detection — CRC remainder is appended; receiver recomputes CRC and checks for match", "Forward error correction (automatic fix without retransmission)"], "correct": 2}'::jsonb,'CRC detects errors by appending a remainder of polynomial division. It can detect all single-bit errors, all burst errors shorter than the CRC length. Unlike ARQ, it does NOT correct errors — it only detects them.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-17','Turbo Code vs Convolutional Code','Hard','ECE','arena','compare','Communication Systems','multiple_choice','Turbo codes (used in 3G/4G) achieve performance very close to Shannon''s capacity limit because:','{"choices": ["They use larger constellation sizes", "They iterate between two interleaved recursive systematic convolutional decoders, passing soft information back and forth to progressively refine decoding", "They use 10× more bandwidth than required", "They operate at higher transmit power"], "correct": 1}'::jsonb,'Turbo codes use two RSC encoders with an interleaver between them. The iterative decoder passes extrinsic (soft) information between component decoders — each iteration improves BER. This achieves within ~0.5 dB of Shannon limit.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-18','MIMO Antenna System Capacity','Hard','ECE','arena','interpret','Communication Systems','multiple_choice','A 4×4 MIMO system (4 transmit, 4 receive antennas) operates in a rich scattering environment. Compared to SISO (1×1), the theoretical channel capacity is approximately:','{"choices": ["The same as SISO", "4× the SISO capacity (same bandwidth, same total power)", "16× the SISO capacity", "2× the SISO capacity"], "correct": 1}'::jsonb,'In rich scattering with ideal channel knowledge, MIMO capacity scales as min(N_T, N_R) × SISO capacity. For 4×4: capacity ≈ 4× SISO. This is the spatial multiplexing gain — 4 independent data streams.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-19','AWGN Channel BER for BPSK','Hard','ECE','arena','interpret','Communication Systems','multiple_choice','For BPSK modulation in AWGN, the BER as a function of E_b/N_0 is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-20','Antenna Gain and Directivity','Hard','ECE','arena','interpret','Communication Systems','multiple_choice','A parabolic dish antenna has diameter D = 1 m at 10 GHz (λ = 30 mm). Aperture efficiency η = 0.6. What is its gain?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-21','Pulse Shaping: Raised Cosine Filter','Hard','ECE','arena','select','Communication Systems','multiple_choice','A raised cosine filter is used in digital communications for pulse shaping because:','{"choices": ["It maximises power efficiency", "It achieves zero ISI at the correct sampling instants while providing spectral roll-off controlled by the roll-off factor α", "It is the easiest digital filter to implement", "It maximises channel bandwidth usage"], "correct": 1}'::jsonb,'The raised cosine filter satisfies the Nyquist ISI criterion: zero crossings at multiples of T. Roll-off factor α (0 to 1) controls bandwidth: α=0 is ideal (brick wall, hard to implement); α=1 doubles bandwidth. Split between Tx (root-RC) and Rx (root-RC).','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-22','Spread Spectrum: FHSS vs DSSS','Hard','ECE','arena','compare','Communication Systems','multiple_choice','FHSS (Frequency Hopping Spread Spectrum) differs from DSSS (Direct Sequence Spread Spectrum) in that:','{"choices": ["FHSS is only used for military communications", "FHSS hops the carrier frequency in a pseudo-random sequence, while DSSS spreads the signal by multiplying with a high-rate PN code at a fixed carrier", "DSSS offers higher data rates than FHSS", "FHSS always uses narrowband transmission"], "correct": 1}'::jsonb,'FHSS changes carrier frequency each hop period (e.g., Bluetooth at 1600 hops/s). DSSS uses a PN code to spread wideband at fixed carrier (e.g., GPS, 802.11b). Both resist jamming and enable multiple access.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-23','Link Budget for Satellite','Hard','ECE','arena','calculate','Communication Systems','multiple_choice','A satellite downlink: EIRP = 50 dBW, free-space loss = 200 dB, receive antenna gain = 40 dBi, receiver noise figure = 2 dB, system noise = −160 dBW/Hz, required C/N = 10 dB, bandwidth = 36 MHz (75.6 dB·Hz). Is the link margin positive?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-24','Equalisation in Multipath Channels','Hard','ECE','arena','select','Communication Systems','multiple_choice','A wireless channel introduces multipath — multiple signal copies arrive with different delays. Without equalisation, this causes:','{"choices": ["Increased signal power", "Inter-Symbol Interference (ISI) — delayed copies overlap and corrupt adjacent symbols", "Narrower signal bandwidth", "Improved receiver sensitivity"], "correct": 1}'::jsonb,'Multipath creates time-dispersive channel: delayed replicas of symbol N arrive during symbol N+1 reception, causing ISI. Equalisers (MLSE, DFE, MMSE) mitigate this. OFDM avoids ISI by using a cyclic prefix longer than the channel delay spread.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-cs-25','5G NR Numerology','Hard','ECE','arena','interpret','Communication Systems','multiple_choice','5G NR uses scalable numerology: subcarrier spacing (SCS) can be 15, 30, 60, 120, or 240 kHz. Why use wider SCS (e.g., 120 kHz) at mmWave frequencies?','{"choices": ["To reduce bandwidth requirements", "Wider SCS reduces symbol duration, making the cyclic prefix shorter relative to the phase noise coherence time — better tolerance to mmWave phase noise and Doppler", "To increase modulation order", "To simplify baseband processing"], "correct": 1}'::jsonb,'mmWave (28/39 GHz) suffers high phase noise and short coherence times. Short OFDM symbol duration (shorter CP) reduces sensitivity. The 120 kHz SCS numerology in FR2 is specifically designed for mmWave operation in 5G NR (3GPP Rel-15+).','{multiple_choice}'::text[],0.45) ON CONFLICT (slug) DO NOTHING;
